actions.script:
const edl = ec.entity.makeDataLoader()
let source = ""
if (types || components) {
    if (types) edl.dataTypes(types.split(","))
    if (components) edl.componentNameList(components.split(","))
    source = `Types: ${types || 'N/A'}, Components: ${components || 'N/A'}`
} else if (location) {
    // Java blocks a remote location in production; the loader here reads local and component locations only
    if (/^https?:/i.test(String(location))) {
        ec.message.addError(ec.l10n.localize("Remote data load location is not allowed"))
        return
    }
    edl.location(location)
    source = location
} else if (csvText) {
    edl.csvText(csvText)
    source = "CSV Text Box"
} else if (jsonText) {
    edl.jsonText(jsonText)
    source = "JSON Text Box"
} else if (xmlText) {
    edl.xmlText(xmlText)
    source = "XML Text Box"
} else {
    ec.message.addMessage(ec.l10n.localize("No parameters specified, not loading data"))
    return
}
if (timeout) edl.transactionTimeout(parseInt(timeout, 10))
if (dummyFks) edl.dummyFks(true)
if (useTryInsert) edl.useTryInsert(true)
if (hideNoActionFiles) edl.messageNoActionFiles(false)
edl.restrictSensitiveEntities(true)

// with wrapForeignKeys the load runs on a worker between the jobs of plan#LoadWrap: the foreign keys of the tables
// in the data are dropped, the data loaded, and the keys made again whatever the load did (the DatabaseLoadWrap
// ServiceJob, moqui.tools.DatabaseLoadServices.run#LoadWrap)
if (!checkOnly && String(context.wrapForeignKeys) == 'true') {
    if (!ec.user.hasPermission('DATABASE_ADMIN')) { ec.message.addError(ec.l10n.localize('A load with the foreign keys dropped needs the DATABASE_ADMIN permission')); return }
    // the entities of the data, read and not written; a load by types or components may touch any table
    let entityNames = []
    if (!(types || components)) {
        const names = new Set()
        for (const value of edl.list()) {
            const name = value && (typeof value.getEntityName === 'function' ? value.getEntityName() : value.entityName)
            if (name) names.add(String(name))
        }
        entityNames = Array.from(names)
        if (!entityNames.length) { ec.message.addError(ec.l10n.localize('The data names no entity to load')); return }
    }
    const wrap = ec.service.sync().name('org.moqui.dev.DatabaseServices.plan#LoadWrap').parameters({db, entityNames,
        description: entityNames.length ? 'Foreign keys around a load of ' + entityNames.length + ' entities' : 'Foreign keys around a load of every entity'}).call() || {}
    if (ec.message.hasError()) return
    for (const warning of wrap.warnings || []) ec.message.addMessage(String(warning), 'warning')
    if (!wrap.dropJobId || !wrap.restoreJobId) { ec.message.addError(String(wrap.jobReason || 'The foreign keys could not be planned')); return }
    const parameters = {dropJobId: wrap.dropJobId, restoreJobId: wrap.restoreJobId, loadKind: 'data',
        onlyCreate: !!onlyCreate, dummyFks: !!dummyFks, useTryInsert: !!useTryInsert}
    for (const name of ['xmlText', 'jsonText', 'csvText', 'location', 'types', 'components']) if (context[name]) parameters[name] = String(context[name])
    if (timeout) parameters.transactionTimeout = parseInt(timeout, 10)
    const jobRunId = ec.service.job('DatabaseLoadWrap').parameters(parameters).run()
    ec.message.addMessage(`Started the load on a worker (job run ${jobRunId}): database job ${wrap.dropJobId} drops ${(wrap.dropStatements || []).length} foreign keys, then the data is loaded, then database job ${wrap.restoreJobId} makes them again. A notification says how it ended; Database › Jobs shows both jobs.`, 'info')
    return
}

if (checkOnly) {
    // do nothing, checkOnly handled in screen actions before render
} else {
    if (onlyCreate) edl.onlyCreate(true)
    const messages = []
    const recordsLoaded = edl.load(messages)
    ec.message.addMessage(`Loaded ${recordsLoaded} records from [${source}]`)
    ec.web.sessionAttributes["DataLoad.messages"] = messages
}

let fieldsUpdated = 0
const rowOpList = rowOps ? rowOps.split(',') : []
for (const rowOp of rowOpList) {
    const rowOpJson = StringUtilities.base64UrlDecode(rowOp)
    const rowOpMap = JSON.parse(rowOpJson)
    if (!rowOpMap.pk) { ec.message.addMessage(`No PK in row: ${rowOpJson}`); continue }

    const ed = ec.entity.getEntityDefinition(rowOpMap.entity)
    if (ed == null) { ec.message.addMessage(`Entity ${rowOpMap.entity} not found for row: ${rowOpJson}`); continue }

    if (rowOpMap.field) {
        const valueMap = Object.assign({}, rowOpMap.pk, {[rowOpMap.field]: rowOpMap.value})
        const stored = ec.entity.makeValue(rowOpMap.entity)
        stored.setFields(valueMap, true, null, null)
        stored.createOrUpdate()
        fieldsUpdated++
    } else if (rowOpMap.createValues) {
        const valueMap = Object.assign({}, rowOpMap.createValues, rowOpMap.pk)
        const created = ec.entity.makeValue(rowOpMap.entity)
        created.setFields(valueMap, true, null, null)
        created.create()
        fieldsUpdated += (Object.keys(valueMap).length - Object.keys(rowOpMap.pk).length)
    } else {
        // TODO: support create (at least for fields with complete PK)
        ec.message.addMessage(`Row has no field or create values, not updating: ${rowOpJson}`)
    }
}

ec.message.addMessage(`Updated ${fieldsUpdated} fields`)

const edl = ec.entity.makeDataLoader()
let source = ""
if (types || components) {
    if (types) edl.dataTypes(types.split(","))
    if (components) edl.componentNameList(components.split(","))
    source = `Types: ${types || 'N/A'}, Components: ${components || 'N/A'}`
} else if (location) {
    edl.location(location)
    source = location
} else if (csvText) {
    edl.csvText(csvText)
    source = "CSV Text Box"
} else if (jsonText) {
    edl.jsonText(jsonText)
    source = "JSON Text Box"
} else if (xmlText) {
    edl.xmlText(xmlText)
    source = "XML Text Box"
} else {
    ec.message.addMessage(ec.l10n.localize("No parameters specified, not loading data"))
    return
}
if (hideNoActionFiles) edl.messageNoActionFiles(false)
edl.restrictSensitiveEntities(true)

messageList = []
diffInfoList = []
fieldsChecked = edl.checkInfo(diffInfoList, messages)

CollectionUtilities.orderMapList(diffInfoList, ['entity', 'pk', 'field'])
CollectionUtilities.paginateList("diffInfoList", null, ec.context)
